<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;use Illuminate\Support\Str;
class AlertRule extends Model{protected $fillable=['tenant_id','server_id','docker_container_id','application_deployment_id','uuid','name','type','metric','operator','threshold','duration_minutes','severity','channels','enabled','last_evaluated_at','last_triggered_at'];protected static function booted():void{static::creating(fn($m)=>$m->uuid??=(string)Str::uuid());}protected function casts():array{return['channels'=>'array','enabled'=>'boolean','last_evaluated_at'=>'datetime','last_triggered_at'=>'datetime','threshold'=>'decimal:2'];}public function getRouteKeyName():string{return'uuid';}public function server():BelongsTo{return $this->belongsTo(Server::class)->withTrashed();}public function container():BelongsTo{return $this->belongsTo(DockerContainer::class,'docker_container_id')->withTrashed();}public function deployment():BelongsTo{return $this->belongsTo(ApplicationDeployment::class,'application_deployment_id')->withTrashed();}public function incidents():HasMany{return $this->hasMany(AlertIncident::class);}}
